<div class="mb-5 flex flex-wrap items-center justify-between gap-3"><div><p class="font-medium"><?=count($categories)?> categorias cadastradas</p><p class="text-sm text-slate-500">Somente categorias ativas e contabilmente configuradas aparecem em receitas e despesas.</p></div><a class="btn btn-primary" href="<?=url('categories/form')?>"><i data-lucide="plus"></i>Nova categoria</a></div>
<div class="card table-wrap"><table class="data-table"><thead><tr><th>Categoria</th><th>Grupo financeiro</th><th>Conta contábil</th><th>Situação</th><th class="text-right">Ações</th></tr></thead><tbody><?php foreach($categories as $c):?><tr><td><div class="font-medium"><?=e($c['name'])?></div><div class="text-xs text-slate-500"><?=e(ucwords(str_replace('_',' ',$c['classification'])))?></div></td><td><?=e($c['financial_category']?:'Não configurado')?></td><td><?php if($c['account_code']):?><div class="font-mono text-xs"><?=e($c['account_code'])?></div><div class="text-xs text-slate-500"><?=e($c['account_name'])?></div><?php else:?><span class="text-amber-600">Revisão necessária</span><?php endif;?></td><td><span class="rounded-full px-2 py-1 text-xs font-semibold <?=$c['active']&&$c['accounting_enabled']?'bg-emerald-100 text-emerald-700':'bg-amber-100 text-amber-700'?>"><?=$c['active']&&$c['accounting_enabled']?'Disponível':'Pendente/inativa'?></span></td><td><div class="flex justify-end gap-2"><a class="btn btn-light !p-2" href="<?=url('categories/form')?>&id=<?=$c['id']?>"><i data-lucide="pencil"></i></a><form method="post" action="<?=url('categories/delete')?>" data-confirm="Excluir esta categoria?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$c['id']?>"><button class="btn btn-light !p-2 text-red-600"><i data-lucide="trash-2"></i></button></form></div></td></tr><?php endforeach;?></tbody></table></div>
